<script setup lang="ts">
import type { AnalysisSummary as PageSummary, SiteAnalysisSummary } from "~/shared/types/analysis";
import { uiLabel } from "~/utils/ui-label";
const props = defineProps<{ summary: PageSummary | SiteAnalysisSummary }>();
const isSite = computed(() => "totalVisitedPages" in props.summary);
</script>
<template><section class="section card report-section report-section--summary"><div class="section-head"><div><h2>QA 결과 요약</h2><p>{{ isSite ? (summary as SiteAnalysisSummary).sitePurpose : (summary as PageSummary).pagePurpose }}</p></div><span class="tag" :class="`tag--${summary.overallStatus === 'passed' ? 'success' : ['failed','analysis_error'].includes(summary.overallStatus) ? 'failed' : 'warning'}`">{{ uiLabel(summary.overallStatus) }}</span></div>
  <div v-if="isSite" class="summary-grid"><div class="metric"><span class="muted">방문 / 분석 페이지</span><strong>{{ (summary as SiteAnalysisSummary).totalVisitedPages }} / {{ (summary as SiteAnalysisSummary).totalAnalyzedPages }}</strong></div><div class="metric"><span class="muted">발견 / 제외 URL</span><strong>{{ (summary as SiteAnalysisSummary).totalDiscoveredUrls }} / {{ (summary as SiteAnalysisSummary).skippedPageCount }}</strong></div><div class="metric"><span class="muted">생성 / 실행 테스트</span><strong>{{ summary.generatedTestCount }} / {{ summary.executedTestCount }}</strong></div><div class="metric"><span class="muted">성공 / 실패</span><strong>{{ summary.successCount }} / {{ summary.failedCount + summary.errorCount }}</strong></div></div>
